<style id="mobile-responsive">
/* ========== GLOBAL OVERFLOW FIX ========== */
body, html { overflow-x: hidden; }

/* ========== LAYOUT CONTAINER ========== */
/* remove min-width that causes horizontal scroll */
.djNglw { min-width: unset !important; }

/* ========== HEADER ========== */
/* search bar wrapper & nav container: fixed 1180px ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¾Ãƒâ€šÃ‚Â¢ fluid */
.iLEnjq { width: 100% !important; padding: 12px 16px !important; box-sizing: border-box; }
.bLEXkl { width: 100% !important; padding: 0 16px !important; box-sizing: border-box; }

@media (max-width: 768px) {
  /* hide main nav menu + right actions, keep logo + hamburger space */
  .fYnnEx { display: none !important; }
  .lenfTy { display: none !important; }
  /* header search bar wrap */
  .iLEnjq { flex-wrap: wrap; gap: 8px; }
  /* hide search bar on very small screens if it causes overflow */
  .jhkxnd { max-width: 100% !important; width: 100% !important; }
  /* sub-nav */
  .bbEdqm { overflow-x: auto; }
  .bLEXkl { overflow-x: auto; }
  .cmxmds { grid-template-columns: repeat(3, auto) !important; overflow-x: auto; gap: 8px; }
  .bbMVoy { grid-template-columns: repeat(3, 1fr) !important; gap: 8px; }
}

/* ========== HERO SECTION ========== */
@media (max-width: 768px) {
  /* hero outer flex wrapper */
  div[style*="flex:0 0 420px"] {
    flex: 1 1 100% !important;
    max-width: 100% !important;
    width: 100% !important;
  }
  /* hero image banner ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â allow full width */
  div[style*="flex:0 0 420px"] img {
    width: 100% !important;
    height: auto !important;
  }
  /* hero right column wrapper ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â was beside image, now below */
  section > div > div[style*="display:flex"] {
    flex-direction: column !important;
    padding: 16px !important;
  }
  /* hero text/button column */
  section > div > div[style*="display:flex"] > div:not([style*="flex:0 0 420px"]) {
    width: 100% !important;
    padding: 0 !important;
  }
}

/* ========== ARTICLE SECTION ========== */
@media (max-width: 768px) {
  div[style*="padding:48px 56px"] {
    padding: 24px 20px !important;
  }
  div[style*="padding:48px 56px"] h2 {
    font-size: 20px !important;
  }
}

/* ========== REVIEWS SECTION ========== */
@media (max-width: 768px) {
  div[style*="grid-template-columns:repeat(auto-fit,minmax(320px"] {
    grid-template-columns: 1fr !important;
  }
  /* review card: remove rigid width constraints */
  div[style*="border-radius:16px"][style*="padding"] {
    min-width: unset !important;
  }
}

/* ========== FAQ SECTION ========== */
/* .khGRrj already has @media(max-width:768px){grid-template-columns:1fr} built in */
@media (max-width: 768px) {
  .khGRrj { padding: 32px 16px !important; }
  .khGRrj h2 { font-size: 20px !important; }
  details summary span:first-child { font-size: 13px !important; }
}

/* ========== PRODUCT / CATEGORY GRIDS ========== */
@media (max-width: 480px) {
  .CuFcG { grid-template-columns: repeat(2, minmax(0, 1fr)) !important; }
  .iMTBZE { grid-template-columns: 1fr !important; }
  .gCjwhq { grid-template-columns: 1fr !important; }
  .bfEYQh { grid-template-columns: repeat(2, 2fr) !important; }
  .gPYEiq { grid-template-columns: repeat(2, 2fr) !important; }
}

/* ========== GENERAL TEXT ========== */
@media (max-width: 480px) {
  h1 { font-size: 20px !important; }
  h2 { font-size: 17px !important; }
}

/* ========== CTA SECTION ========== */
@media (max-width: 768px) {
  .hhbwLU { padding: 32px 20px !important; border-radius: 16px !important; }
  .hUKNFd { font-size: 20px !important; }
}

/* ========== FOOTER ========== */
@media (max-width: 768px) {
  .cBPqlo { grid-template-columns: 1fr !important; gap: 24px !important; }
}
</style>

